import { describe, expect, it } from 'vitest';
import { AGENT_COMMANDS } from './agent-templates.js';

/**
 * The templates are what the agent actually reads, so the invariants that matter
 * are: names are usable as command names, descriptions fit the Agent Skills
 * limit, and no template ever asks the agent to write plan documents itself —
 * PlanMo owns every generated byte.
 */
describe('agent command templates', () => {
  it('has unique, command-safe names', () => {
    const names = AGENT_COMMANDS.map((c) => c.name);
    expect(new Set(names).size).toBe(names.length);
    expect(names.length).toBeGreaterThan(0);
    for (const name of names) {
      expect(name, name).toMatch(/^[a-z][a-z0-9-]*$/);
    }
  });

  it('keeps descriptions within the Agent Skills limit', () => {
    for (const command of AGENT_COMMANDS) {
      expect(command.description.length, command.name).toBeGreaterThan(0);
      expect(command.description.length, command.name).toBeLessThanOrEqual(1024);
    }
  });

  it('descriptions are single-line (frontmatter safety)', () => {
    for (const command of AGENT_COMMANDS) {
      expect(command.description, command.name).not.toContain('\n');
    }
  });

  it('never asks the agent to write plan documents itself', () => {
    for (const command of AGENT_COMMANDS) {
      expect(command.body, command.name).not.toMatch(/write .*planning\//i);
    }
  });

  it('tells the agent to run the CLI rather than invent a plan', () => {
    const all = AGENT_COMMANDS.map((c) => c.body).join('\n');
    expect(all).toContain('npx planmo');
  });
});
